import * as pdfjs from './vendor/pdf.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
import createVerovioModule from './vendor/verovio-module.mjs';
import {VerovioToolkit} from './vendor/verovio.mjs';
import {buildScore,passage,FollowNotes} from './score-core.mjs';
const q=id=>document.getElementById(id),status=text=>q('lib-status').textContent=text;
const note=n=>['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][n%12]+(Math.floor(n/12)-1);
let toolkitPromise,tk,record,score,range,follow,currentQ=0,shown=-1,timer,mode='',selectedId='',pdfUrl='',pdfDocument=null,pdfPage=1,pdfRender=null;const matched=new Set();
const ready=()=>toolkitPromise??=(createVerovioModule().then(module=>tk=new VerovioToolkit(module)));
const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('piano-score-library',1);r.onupgradeneeded=()=>r.result.createObjectStore('scores',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function persist(value){try{const db=await dbPromise;await new Promise((resolve,reject)=>{const tx=db.transaction('scores','readwrite');tx.objectStore('scores').put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});await refreshSaved()}catch(e){status('Browser storage unavailable or full. Keep your original file; this score may not survive a reload.')}}
async function records(){const db=await dbPromise;return new Promise((resolve,reject)=>{const r=db.transaction('scores').objectStore('scores').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function refreshSaved(){const list=await records();q('lib-saved').replaceChildren(new Option('Choose a saved score',''));list.forEach(r=>q('lib-saved').append(new Option(r.name,r.id)));if(record)q('lib-saved').value=record.id}
function stop(){document.querySelectorAll('#um-keys .pkey').forEach(key=>key.classList.remove('held','attack'));q('lib-notation').querySelectorAll('.note').forEach(el=>el.classList.remove('lib-expected','lib-held'));window.importedPracticeActive=false;clearTimeout(timer);timer=null;mode='';if(follow)follow.active=false;window.pianoPractice?.stop();q('lib-progress').textContent='Stopped · restart the selected passage';}
window.addEventListener('piano-midi-reset',stop);window.addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
for(const id of ['um-play','um-practice','um-stop','um-prev','um-next'])q(id)?.addEventListener('click',()=>{clearTimeout(timer);timer=null;mode='';if(follow)follow.active=false});
function safeSvg(text){const dom=new DOMParser().parseFromString(text,'image/svg+xml');for(const node of dom.querySelectorAll('script,foreignObject'))node.remove();for(const node of dom.querySelectorAll('*'))for(const a of [...node.attributes])if(a.name.startsWith('on')||(a.name.endsWith('href')&&!a.value.startsWith('#')))node.removeAttribute(a.name);return new XMLSerializer().serializeToString(dom.documentElement)}
function measureIndex(t){let i=score.measures.findIndex(m=>m.start<=t&&t<m.end);return i<0?range.last:i}
function draw(){window.importedPracticeActive=mode==='practice';if(!score||!range)return;const m=measureIndex(currentQ);if(m!==shown){tk.select({measureRange:String(m+1)});tk.redoLayout();q('lib-notation').innerHTML=safeSvg(tk.renderToSVG(1));shown=m}q('lib-notation').querySelectorAll('.note').forEach(el=>el.classList.remove('lib-expected','lib-matched','lib-held'));for(const seg of score.segments.filter(s=>s.measure===m)){const el=q('lib-notation').querySelector('[id="'+CSS.escape(seg.id)+'"]');if(!el)continue;let state=matched.has(seg.root)?'lib-matched':'';if(mode&&seg.t<=currentQ&&currentQ<seg.end){const e=range.events.find(e=>e.id===seg.root);state=e?.t===currentQ?(follow?.collected.has(seg.n)?'lib-matched':'lib-expected'):'lib-held'}if(state)el.classList.add(state)}document.querySelectorAll('#um-keys .pkey').forEach(key=>{const n=+key.dataset.note;key.classList.toggle('attack',!!mode&&range.events.some(e=>e.n===n&&e.t===currentQ));key.classList.toggle('held',!!mode&&range.events.some(e=>e.n===n&&e.t<currentQ&&currentQ<e.t+e.d))});const group=mode==='practice'?follow?.current:null;q('lib-progress').textContent='Measure '+score.measures[m].label+(group?' · Play '+group.notes.filter(n=>!follow.collected.has(n)).map(n=>note(n)+' (MIDI '+n+')').join(' + '):'')+(mode==='listen'?' · Listening once':'');}
function useRange(){stop();const a=+q('lib-first').value,b=+q('lib-last').value;range=passage(score,a,b);currentQ=range.start;if(range.events.length)window.pianoPractice?.setKeyboardRange(Math.max(21,Math.min(40,...range.events.map(e=>e.n))),Math.min(108,Math.max(72,...range.events.map(e=>e.n))));follow=new FollowNotes(range.groups);follow.active=false;matched.clear();q('lib-reviewed').checked=false;shown=-1;draw();status('Passage selected. Compare the engraved notes with your original before note practice.');}
async function loadNotation(value){stop();selectedId='';q('lib-note').textContent='None';q('lesson-title').textContent=value.name;q('lesson-subtitle').textContent='Imported score · review before practice';record=value;status('Loading notation…');await ready();tk.setOptions({breaks:'auto',pageWidth:1000,pageHeight:1600,scale:45,adjustPageHeight:true,mnumInterval:1,svgHtml5:false,svgViewBox:true,svgRemoveXlink:true});tk.select({});const ok=value.mxl?tk.loadZipDataBase64(value.mxl):tk.loadData(value.notation);if(!ok)throw Error('This file could not be read as MusicXML or MEI');score=buildScore(tk);if(!score.events.length||!score.measures.length)throw Error('No playable notes were recognized');record.notation=score.mei;delete record.mxl;q('lib-score-tools').hidden=false;q('lib-first').replaceChildren();q('lib-last').replaceChildren();score.measures.forEach((m,i)=>{q('lib-first').append(new Option(m.label,String(i)));q('lib-last').append(new Option(m.label,String(i)))});q('lib-last').value=String(Math.min(score.measures.length-1,3));q('lib-reviewed').checked=false;shown=-1;useRange();status((value.partial?'INCOMPLETE OMR — some pages may be missing. ':value.omr?'OMR draft — not verified. ':'Imported notation. ')+score.measures.length+' measures, '+score.events.length+' attacks. Review pitches, rhythm, missing notes, and ties against the original.');await persist(record)}
async function renderPdf(){if(!pdfDocument)return;if(pdfRender){try{await pdfRender.promise}catch{}}const page=await pdfDocument.getPage(pdfPage);const available=Math.min(1000,q('score-library').clientWidth-24);const base=page.getViewport({scale:1});const viewport=page.getViewport({scale:Math.max(1,available/base.width)*Math.min(window.devicePixelRatio||1,2)});const canvas=q('lib-pdf');canvas.width=viewport.width;canvas.height=viewport.height;canvas.style.width=Math.min(available,base.width*2)+'px';pdfRender=page.render({canvasContext:canvas.getContext('2d'),viewport});await pdfRender.promise;q('lib-pdf-page').textContent='PDF page '+pdfPage+' of '+pdfDocument.numPages;}
q('lib-pdf-prev').onclick=()=>{if(pdfDocument){pdfPage=Math.max(1,pdfPage-1);renderPdf().catch(e=>status(e.message))}};q('lib-pdf-next').onclick=()=>{if(pdfDocument){pdfPage=Math.min(pdfDocument.numPages,pdfPage+1);renderPdf().catch(e=>status(e.message))}};
function showPdf(value){q('lesson-title').textContent=value.name;q('lesson-subtitle').textContent=value.notation||value.mxl?'Imported score · review before practice':'PDF score · recognition required for practice';if(!value.notation&&!value.mxl){score=null;range=null;shown=-1}if(pdfUrl)URL.revokeObjectURL(pdfUrl);q('lib-pdf-tools').hidden=!value.pdf;if(value.pdf){pdfUrl=URL.createObjectURL(value.pdf);q('lib-original').href=pdfUrl;pdfPage=1;value.pdf.arrayBuffer().then(data=>pdfjs.getDocument({data:new Uint8Array(data),isEvalSupported:false}).promise).then(doc=>{pdfDocument=doc;return renderPdf()}).catch(e=>status('PDF display failed: '+e.message))}q('lib-score-tools').hidden=!value.notation&&!value.mxl;}
q('lib-file').onchange=async()=>{const file=q('lib-file').files[0];if(!file)return;if(file.size>50*1024*1024){status('Choose a score smaller than 50 MB.');return}try{stop();record={id:crypto.randomUUID(),name:file.name,created:Date.now(),originalFile:file};if(/\.pdf$/i.test(file.name)){record.pdf=file;record.omr=true;showPdf(record);await persist(record);status('PDF saved and ready to view. Choose Recognize notes to extract notation locally.')}else{if(/\.mxl$/i.test(file.name)){const bytes=new Uint8Array(await file.arrayBuffer());let str='';for(const b of bytes)str+=String.fromCharCode(b);record.mxl=btoa(str)}else record.notation=await file.text();showPdf(record);await loadNotation(record)}}catch(e){status('Import failed: '+e.message)}};
q('lib-saved').onchange=async()=>{try{const value=(await records()).find(r=>r.id===q('lib-saved').value);if(!value)return;record=value;showPdf(value);if(value.notation||value.mxl)await loadNotation(value);else{stop();status('Saved PDF opened. Recognize notes to enable practice.')}}catch(e){status(e.message)}};
q('lib-range').onclick=()=>{try{useRange()}catch(e){status(e.message)}};
q('lib-stop').onclick=stop;
q('lib-listen').onclick=()=>{if(!range)return;stop();window.dispatchEvent(new Event('stop-original-practice'));mode='listen';matched.clear();currentQ=range.start;shown=-1;const tempo=Math.max(20,Math.min(200,+q('lib-tempo').value||60));const points=[...new Set([range.start,range.end,...range.events.flatMap(e=>[e.t,Math.min(range.end,e.t+e.d)]),...score.segments.filter(s=>s.t>=range.start&&s.t<range.end).map(s=>s.t)])].sort((a,b)=>a-b);let i=0;function tick(){if(mode!=='listen')return;currentQ=points[i];if(currentQ>=range.end){mode='';window.pianoPractice?.stop();draw();q('lib-progress').textContent='Passage complete · Listen once or Start practice to restart';return}draw();range.events.filter(e=>Math.abs(e.t-currentQ)<.00001).forEach(e=>window.pianoPractice?.tone(e.n,e.d*60/tempo));const delay=(points[i+1]-currentQ)*60000/tempo;i++;timer=setTimeout(tick,delay)}tick()};
q('lib-practice').onclick=()=>{if(!range)return;if(!q('lib-reviewed').checked){status('Review the selected passage against the original, then check the review box before practicing.');return}stop();window.dispatchEvent(new Event('stop-original-practice'));follow=new FollowNotes(range.groups);if(!follow.active){status('This passage has no note attacks.');return}mode='practice';matched.clear();currentQ=follow.current.t;shown=-1;draw()};
window.addEventListener('piano-midi',event=>{if(mode!=='practice'||!event.detail.attack)return;const n=event.detail.note;if(follow.current.notes.includes(n))for(const e of follow.current.events.filter(e=>e.n===n))matched.add(e.id);const result=follow.attack(n);if(result==='finished'){mode='';draw();q('lib-progress').textContent='Passage complete · restart explicitly to play again';return}if(result==='advanced')currentQ=follow.current.t;draw();if(result==='wrong')q('lib-progress').textContent+=' · Heard '+note(n)+', waiting for expected notes';});
for(const [id,delta] of [['lib-prev',-1],['lib-next',1]])q(id).onclick=()=>{if(!range)return;stop();currentQ=score.measures[Math.max(range.first,Math.min(range.last,measureIndex(currentQ)+delta))].start;draw()};
q('lib-notation').onclick=event=>{const el=event.target.closest('.note');if(!el)return;selectedId=el.id;const segment=score.segments.find(s=>s.id===selectedId);if(!segment)return;q('lib-note').textContent=note(segment.n)+' (MIDI '+segment.n+')';q('lib-pitch').value=segment.n;};
q('lib-correct').onclick=async()=>{try{if(!selectedId)throw Error('Click a notehead first');stop();const n=+q('lib-pitch').value;if(!Number.isInteger(n)||n<0||n>127)throw Error('MIDI pitch must be 0–127');const doc=new DOMParser().parseFromString(record.notation,'application/xml');const el=[...doc.getElementsByTagName('note')].find(e=>e.getAttribute('xml:id')===selectedId);if(!el)throw Error('Selected note is no longer available');const steps=['c','c','d','d','e','f','f','g','g','a','a','b'];el.setAttribute('pname',steps[n%12]);el.setAttribute('oct',Math.floor(n/12)-1);el.removeAttribute('pnum');el.removeAttribute('accid');el.removeAttribute('accid.ges');for(const a of [...el.getElementsByTagName('accid')])a.remove();const a=doc.createElementNS('http://www.music-encoding.org/ns/mei','accid');a.setAttribute('accid',[1,3,6,8,10].includes(n%12)?'s':'n');el.append(a);record.notation=new XMLSerializer().serializeToString(doc);await loadNotation(record);status('Pitch correction saved. Review the updated notation and ties before practicing.')}catch(e){status(e.message)}};
q('lib-export').onclick=()=>{if(!record?.notation)return;const url=URL.createObjectURL(new Blob([record.notation],{type:'application/xml'})),a=document.createElement('a');a.href=url;a.download=record.name.replace(/\.[^.]+$/,'')+'-review.mei';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
q('lib-convert').onclick=async()=>{if(!record?.pdf)return;const target=record;q('lib-convert').disabled=true;try{status('Connecting to local Audiveris converter…');const response=await fetch('http://127.0.0.1:8937/jobs',{method:'POST',headers:{'Content-Type':'application/pdf','X-Score-Request':'1'},signal:AbortSignal.timeout(15000),body:target.pdf});const job=await response.json();if(!response.ok)throw Error(job.error||'Converter rejected the file');status('Recognizing music locally. This can take several minutes.');while(true){await new Promise(resolve=>setTimeout(resolve,2000));const r=await fetch('http://127.0.0.1:8937/jobs/'+job.id,{headers:{'X-Score-Request':'1'},signal:AbortSignal.timeout(15000)}),state=await r.json();if(state.status==='failed')throw Error(state.error);if(state.status==='complete'){target.notation=state.xml;target.omr=true;target.partial=!!state.partial;if(record.id===target.id)await loadNotation(target);else await persist(target);if(state.warning)status(state.warning);break}}}catch(e){status('PDF recognition unavailable: '+e.message+'. Open start-score-converter.command from your Codex outputs folder, then retry. You can still view the PDF or import corrected MusicXML.')}finally{q('lib-convert').disabled=false}};
q('lib-demo').onclick=async()=>{try{status('Opening full-score OMR draft…');const [xml,pdf]=await Promise.all([fetch('una-mattina-full.mei').then(r=>{if(!r.ok)throw Error('Full-score draft is not available');return r.text()}),fetch('una-mattina-original.pdf').then(r=>r.blob())]);const value={id:'una-mattina-omr-draft',name:'Una Mattina · full-score OMR draft (review required)',notation:xml,pdf,omr:true};record=value;showPdf(value);await loadNotation(value)}catch(e){status(e.message)}};
refreshSaved().catch(()=>status('Browser storage unavailable. File imports still work for this visit.'));

q('score-library').addEventListener('toggle',()=>{if(!q('score-library').open){stop();q('lesson-title').textContent='Una Mattina';q('lesson-subtitle').textContent='Guided piano practice · measures 36–40';window.pianoPractice?.showOriginal()}else window.pianoPractice?.stop()});
